          this.nameToBit = {};
          this.bitToName = {};
          this.MASK = {};

          moduleNames.forEach((name, index) => {
              const bit = 1 << index;
              this.nameToBit[name] = bit;
              this.bitToName[bit] = name;
              this.MASK[name] = bit;
          });

